public static String trimTrailingWhitespace(String str) {
    if (str == null) {
        return null;
    }
    int end = str.length() - 1;
    while (end >= 0 && Character.isWhitespace(str.charAt(end))) {
        end--;
    }
    if (end == str.length() - 1) {
        return str;
    }
    return str.substring(0, end + 1);
}

