public static String applyRelativePath(String path, String relativePath) {
    if (path == null) path = "";
    if (relativePath == null || relativePath.isEmpty()) return path;
    String[] pathParts = path.split("/");
    ArrayDeque<String> stack = new ArrayDeque<>();
    for (String part : pathParts) {
        if (part.isEmpty() || part.equals(".")) continue;
        if (part.equals("..")) {
            if (!stack.isEmpty()) stack.removeLast();
        } else {
            stack.addLast(part);
        }
    }
    String[] relParts = relativePath.split("/");
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) continue;
        if (part.equals("..")) {
            if (!stack.isEmpty()) stack.removeLast();
        } else {
            stack.addLast(part);
        }
    }
    StringBuilder result = new StringBuilder();
    for (String part : stack) {
        result.append("/").append(part);
    }
    // If the original path started with a '/', preserve root
    if (path.startsWith("/") || result.length() == 0) {
        return result.length() == 0 ? "" : result.toString();
    }
    // Remove leading slash if path was relative
    return result.length() > 0 ? result.substring(1) : "";
}

