 * Find the value corresponding to <code>key</code> in <code>props</code>. Then perform variable substitution on the found value.
 */

codes:
public static String findAndSubst(String key, Properties props) {
    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    int index = 0;
    while (index < value.length()) {
        int start = value.indexOf("${", index);
        if (start == -1) {
            result.append(value.substring(index));
            break;
        }
        result.append(value.substring(index, start));
        int end = value.indexOf('}', start + 2);
        if (end == -1) {
            result.append(value.substring(start));
            break;
        }
        String var = value.substring(start + 2, end);
        String replacement = props.getProperty(var);
        if (replacement == null) {
            replacement = "${" + var + "}";
        }
        result.append(replacement);
        index = end + 1;
    }
    return result.toString();
}

