public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (name == null || nameStart >= name.length()) {
        return;
    }
    int len = name.length();
    int current = nameStart;
    while (current < len) {
        int nextDot = name.indexOf('.', current);
        if (nextDot == -1) {
            // last component: append it entirely
            buf.append(name, current, len);
            break;
        }
        // Append abbreviation of the current component (first character)
        if (current < nextDot) {
            buf.append(name.charAt(current));
        }
        // Append the dot separator
        buf.append('.');
        // Move to the start of the next component
        current = nextDot + 1;
    }
}

