public Mappings diffStructure(String tableName, Mappings mappings){
    // Retrieve the current index mappings for the specified table
    Mappings currentMappings = getCurrentMappings(tableName);

    // Prepare the result object
    Mappings diff = new Mappings();

    // Assume that Mappings exposes its internal map via getMappings()
    Map<String, Object> currentMap = currentMappings.getMappings();
    Map<String, Object> historyMap = mappings.getMappings();

    for (String field : currentMap.keySet()){
        // Skip the special _source configuration
        if ("_source".equals(field)){
            continue;
        }
        // If the field is missing from the history mapping, add it to the diff
        if (!historyMap.containsKey(field)){
            diff.addMapping(field, currentMap.get(field));
        }
    }

    return diff;
}

