public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (len <= 0 || str == null) {
        return 0;
    }
    int end = index + len;
    if (end > str.length()) {
        end = str.length();
    }
    int size = 0;
    int i = index;
    while (i < end) {
        int cp = Character.codePointAt(str, i);
        if (cp <= 0x7F) {
            size += 1;
        } else if (cp <= 0x7FF) {
            size += 2;
        } else if (cp <= 0xFFFF) {
            size += 3;
        } else {
            size += 4;
        }
        i += Character.charCount(cp);
    }
    return size;
}

