public long readRawVarint64() throws IOException {
    byte b;
    long result = 0;
    int shift = 0;
    for (;;) {
        if (shift == 64) {
            // Varint is too long, corrupt data
            throw new IOException("Varint too long");
        }
        b = read(); // read() should return next byte or -1 on EOF
        if (b < 0) {
            throw new EOFException("Stream ended prematurely");
        }
        result |= (long) (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return result;
        }
        shift += 7;
    }
}

